def transform(grid):
    h, w = len(grid), len(grid[0])
    # Divider color appears in completely uniform rows and columns.
    divider = next(
        grid[r][0] for r in range(h)
        if all(x == grid[r][0] for x in grid[r])
    )
    divider_rows = [r for r in range(h) if all(x == divider for x in grid[r])]
    divider_cols = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    rb = [-1] + divider_rows + [h]
    cb = [-1] + divider_cols + [w]

    from collections import Counter
    counts = Counter(x for row in grid for x in row if x != divider)
    background = counts.most_common(1)[0][0]
    marker = min(counts, key=counts.get)

    result = []
    for i in range(len(rb) - 1):
        out_row = []
        for j in range(len(cb) - 1):
            cells = [
                grid[r][c]
                for r in range(rb[i] + 1, rb[i + 1])
                for c in range(cb[j] + 1, cb[j + 1])
            ]
            out_row.append(1 if cells.count(marker) == 2 else background)
        result.append(out_row)
    return result
